 4: set(range(2,259,4))|set(range(263,579,5))|set(range(584,957,6)),
}
# also assume positions 0,1,2 are checked for a=1
def sim(model, a, N=1300):
    pos=[0]; step=1; smn = a<<6
    while True:
        p=pos[-1]
        if p>N: break
        # model gives the next step
        ns = model(a, len(pos)-1, step, smn, p)
        pos.append(p+ns)
        step = ns
        smn += 1
    return set(pos)
def m1(a,i,step,smn,p):   # check, then step=(smn>>6), then pos+=step
    return (smn>>6) if i>0 else 1
def m2(a,i,step,smn,p):   # step=(smn>>6) then pos+=step
    return (smn>>6) if i>0 else 1
def m3(a,i,step,smn,p):
    return max(1, smn>>6)
def m4(a,i,step,smn,p):
    return 1 + ((i-2)>>6) if i>=2 else 1
def m5(a,i,step,smn,p):  # step = 1 for first two, then (a<<6 + i)>>6 ...
    if i<2: return 1
    return ((a<<6) + (i-2))>>6
def m6(a,i,step,smn,p):  # step = (smn>>6) but smn starts at a<<6-2
    return max(1,(smn-2)>>6)
