            while True:
                b=c[i]; i+=1; ll+=b
                if b!=255: break
        lits=c[i:i+ll]; i+=ll
        lit_total+=ll
        if i>=len(c):
            seqs.append((ll,None,None)); break
        off=struct.unpack('<H', c[i:i+2])[0]; i+=2
        if ml==15:
            while True:
                b=c[i]; i+=1; ml+=b
                if b!=255: break
        ml+=4
        seqs.append((ll,off,ml))
    return seqs, lit_total
```
