#include <string.h>

#define MIN_MATCH      4
#define LASTLITERALS   5
#define MFLIMIT        12
#define RUN_MASK       15
#define ML_MASK        15
#define DISTANCE_MAX   65535
#define SKIP_TRIGGER   6

