static uint32_t rd16(const uint8_t* p) { return p[0] | (p[1] << 8); }

void lz4_reset_stream(lz4_stream_t* s) { memset(s, 0, sizeof(*s)); }

static int match_count(const uint8_t* a, const uint8_t* b, const uint8_t* limit)
{
    int n = 0;
    while (a + 4 <= limit && rd32(a) == rd32(b)) { a += 4; b += 4; n += 4; }
    while (a < limit && *a == *b) { a++; b++; n++; }
    return n;
}

