/* LZ4 block codec - fast compressor + safe decompressor (reimplementation) */
#include "lz4block.h"
#include <string.h>

#define MIN_MATCH      4
#define LASTLITERALS   5
#define MFLIMIT        12
#define RUN_MASK       15
#define DISTANCE_MAX   65535
#define SKIP_TRIGGER   6
#define HASH_PRIME     2654435761U
#define BYU16_HASHLOG  13
#define BYU32_HASHLOG  12

static inline uint32_t rd32(const uint8_t* p) { uint32_t v; memcpy(&v, p, 4); return v; }
static inline void wr16(uint8_t* p, uint32_t v) { p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8); }

void lz4_reset_stream(lz4_stream_t* s) { memset(s, 0, sizeof(*s)); }

static inline int match_count(const uint8_t* a, const uint8_t* b, const uint8_t* limit)
{
    const uint8_t* start = a;
    while (a + 4 <= limit && rd32(a) == rd32(b)) { a += 4; b += 4; }
    while (a < limit && *a == *b) { a++; b++; }
    return (int)(a - start);
}

static int lz4_compress_generic(lz4_stream_t* cctx, const uint8_t* src, int srcSize,
                                uint8_t* dst, int dstCapacity, int accelEff, int byU16);

int lz4_compress_fast(lz4_stream_t* cctx, const uint8_t* src, int srcSize,
                      uint8_t* dst, int dstCapacity, int accel, int tableMode)
{
    int byU16;
    int accelEff = accel > 0 ? accel : 1;
    if (srcSize <= 0) return 0;
    if (tableMode == 0) tableMode = (srcSize < 65536) ? 1 : 2;
    byU16 = (tableMode == 1);
    lz4_reset_stream(cctx);
    return lz4_compress_generic(cctx, src, srcSize, dst, dstCapacity, accelEff, byU16);
}

static int lz4_compress_generic(lz4_stream_t* cctx, const uint8_t* src, int srcSize,
                                uint8_t* dst, int dstCapacity, int accelEff, int byU16)
{
    const uint8_t* ip = src;
    const uint8_t* anchor = ip;
    const uint8_t* const iend = ip + srcSize;
    const uint8_t* const mflimit = iend - MFLIMIT;
    const uint8_t* const matchlimit = iend - LASTLITERALS;
    uint8_t* op = dst;
    uint8_t* const oMaxLimited = op + dstCapacity;
    const uint8_t* const base = src;
    const uint8_t* const lowLimit = src;
    const uint32_t maxDistance = DISTANCE_MAX;
    uint32_t* const tbl32 = cctx->hashTable;
    uint16_t* const tbl16 = (uint16_t*)cctx->hashTable;
    const int hshift = byU16 ? (32 - BYU16_HASHLOG) : (32 - BYU32_HASHLOG);

    if (srcSize < MFLIMIT + MIN_MATCH) goto _last_literals;

    while (ip < mflimit) {
        const uint8_t* match;
        {
            const uint8_t* forwardIp = ip;
            int step = 1;
            int iter = 0;
            do {
                uint32_t h = (rd32(forwardIp) * HASH_PRIME) >> hshift;
                const uint8_t* cand = byU16 ? base + tbl16[h] : base + tbl32[h];
                if (cand < forwardIp && cand + maxDistance >= forwardIp
                    && rd32(cand) == rd32(forwardIp)) {
                    match = cand;
                    break;
                }
                if (byU16) tbl16[h] = (uint16_t)(forwardIp - base);
                else       tbl32[h] = (uint32_t)(forwardIp - base);
                forwardIp += step;
                step = (iter < 2) ? 1 : (accelEff + ((iter - 2) >> SKIP_TRIGGER));
                iter++;
                if (forwardIp > mflimit) goto _last_literals;
            } while (1);
        }

        /* Catch up */
        while (ip > anchor && match > lowLimit && ip[-1] == match[-1]) { ip--; match--; }

