            }
        }

        /* Prepare next loop */
        ++ip;
    }

_last_literals:
    {
        size_t lastRunSize = (size_t)(iend - anchor);
        if (op + lastRunSize + 1 + ((lastRunSize + 255 - RUN_MASK) / 255) > oMaxLimited) return 0;
