import subprocess, struct, random, sys
EXE = "/workspace/executable"
MY  = "/tmp/t1"

def oracle_legacy(data, accel=1):
    p = subprocess.run([EXE, "--fast=%d"%accel, "-l", "-c"], input=data, capture_output=True)
    assert p.returncode == 0, p.stderr
    d = p.stdout
    sz = struct.unpack('<I', d[4:8])[0]
    assert d[:4] == b'\x02\x21\x4c\x18', d[:4].hex()
    return d[8:8+sz]

def mine(data, accel=1):
    p = subprocess.run([MY, str(accel)], input=data, capture_output=True)
    return p.stdout

def randdata(n, seed):
    r = random.Random(seed)
    return bytes(r.randrange(256) for _ in range(n))

def runtest(nlist, accel=1, verbose=False):
    bad = 0
    for n in nlist:
        for seed in range(3):
            d = randdata(n, seed*1000+n)
            o = oracle_legacy(d, accel)
            m = mine(d, accel)
