import sys; sys.path.insert(0,'/tmp')
from dt import oracle_legacy
import random
random.seed(11)
words = [b'the', b'quick', b'brown', b'fox', b'jumps', b'over', b'lazy', b'dog', b'\n', b' ']
tests=[]
tests.append(('text600', b''.join(random.choice(words) for _ in range(600))))
r=random.Random(3)
blk=bytes(r.randrange(256) for _ in range(50))
tests.append(('blkrep', blk*40))
tests.append(('rep7', bytes(r.randrange(256) for _ in range(7))*100))
tests.append(('banded', bytes((i//7)%256 for i in range(1000))))
tests.append(('seq', bytes(range(256))*3))
h=bytes(r.randrange(256) for _ in range(200))
tests.append(('half', h+h))
fast_out = {}
for a in range(1,17):
    fast_out[a] = {n: oracle_legacy(d, a) for n,d in tests}
for lvl in range(2,13):
    hc = {n: oracle_legacy(d, lvl) for n,d in tests}
    match=[]
    for a in range(1,17):
        if all(fast_out[a][n]==hc[n] for n,d in tests): match.append(a)
    print("lvl=%2d matches fast accel: %s"%(lvl, match))
PYEOF
python3 /tmp/hcmap.py"}

